#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""إدخال سبعة قوانين غائبة عن القاعدة من «مجموعة من التشريعات الكويتية» (التعديلات حتى 2026/10/5).

بأمر المالك («هذي التشريعات لغاية يوم 5 أكتوبر 2026 — فهرس الناقص غير الموجود بالنظام»):
قوبلت قائمة المرجع (≈68 قانونًا) بالجرد الحي ثم بمسبار بحث دلالي لكل مرشح، فثبت غياب سبعة:
  12/1963 اللائحة الداخلية لمجلس الأمة · 120/2023 انتخابات أعضاء مجلس الأمة · 15/1959 الجنسية
  الكويتية · 63/2015 مكافحة جرائم تقنية المعلومات · 37/2014 هيئة تنظيم الاتصالات · 61/2015
  كاميرات وأجهزة المراقبة الأمنية · 70/2020 مزاولة مهنة الطب وحقوق المرضى
(والعنف الأسري في القاعدة بصيغته النافذة 11/2026، ونظام الخدمة المدنية 1979 موجود بالبادئة legis-nsm-1979.)

المصدر نسخة Markdown مستخرجة آليًا من طبقة نص PDF (لا الجريدة الرسمية) — فالأمانة هنا ثلاث طبقات:
  1. تنقية آلية بقواعد حتمية معدودة لكل قانون (fix_counts في ميتاداتا الديباجة): تسلسلات الأرقام
     الهندية المقلوبة، «( )16»←«(16)»، تشكيل مشقوق بمسافة، حواشٍ مدسوسة في السطر، علامات الإحالة.
  2. ما لا يُصلح حتميًا (كلمة مشقوقة نُقل نصفها لسطر آخر، حرف منفصل) لا يُخمَّن: المادة تُوسم
     extraction_uncertain + verification_status=machine_pending_human + source_note ظاهرة (§15) تقول
     للمحامي والنموذج «يُراجع بالجريدة الرسمية قبل الاقتباس الحرفي».
  3. كل كائن يحمل text_provenance صريحًا، والقانون كله verification_status=operationally_accepted
     (لا source_verified — لم يقابَل بالجريدة).
مواد غائبة عن المرجع نفسه لم تُختلق (70/2020 م25؛ 37/2014 م69) — مسجَّلة في ميتاداتا الديباجة.
تصحيح وحيد موثق: 120/2023 م35 (عنوانها جاء بعد نصّها في طبقة النص) — source_correction.
رقم قانون الكاميرات 61/2015 من متنه (فهرس المرجع يقول 6) — title_note.

الحُرّاس (معاملة واحدة؛ أي فشل ⇒ ROLLED_BACK بلا أثر):
  PREFIX_COLLISION (أي معرّف قائم بالبادئات ليس من هذه الدفعة) · PUBSCRUB_FAIL · RECORD_COUNT ·
  SCOPE_BREACH (بصمة md5 لكل ما سواها) · COUNT_UNEXPECTED
  --rollback FILE يحذف ما أدخلته هذه الدفعة وحدها (الصفوف ونقاط Qdrant) — لا يمسّ غيرها.
  --snapshot-out FILE لقطة كاملة لكل صفّ قائم قبل تحديثه (إعادة التشغيل تُحدِّث الصفوف — ON CONFLICT DO UPDATE)،
  و--restore FILE يعيدها حرفيًا بكل أعمدتها؛ فالتراجع الكامل = --rollback ثم --restore ثم فهرسة تفاضلية.

  .venv/bin/python tools/ingest_reference_missing_20261005.py --ids-out FILE --snapshot-out FILE
  .venv/bin/python tools/ingest_reference_missing_20261005.py --rollback FILE
  .venv/bin/python tools/ingest_reference_missing_20261005.py --restore FILE
"""
